{"path":"test/port.test.mjs","content":"import test from 'node:test';
import assert from 'node:assert/strict';
import { parsePort } from '../src/port.mjs';

// Test valid boundaries
test('valid minimum port (1)', () => {
  assert.equal(parsePort('1'), 1);
});

test('valid maximum port (65535)', () => {
  assert.equal(parsePort('65535'), 65535);
});

test('valid middle port (8080)', () => {
  assert.equal(parsePort('8080'), 8080);
});

test('valid port with leading zeros', () => {
  assert.equal(parsePort('0080'), 80);
});

// Test invalid syntax
test('invalid syntax: non-numeric string', () => {
  assert.throws(() => parsePort('abc'), TypeError);
});

test('invalid syntax: empty string', () => {
  assert.throws(() => parsePort(''), TypeError);
});

test('invalid syntax: negative number string', () => {
  assert.throws(() => parsePort('-80'), TypeError);
});

test('invalid syntax: float string', () => {
  assert.throws(() => parsePort('80.5'), TypeError);
});

test('invalid syntax: decimal point without digits', () => {
  assert.throws(() => parsePort('.'), TypeError);
});

test('invalid syntax: letters and numbers', () => {
  assert.throws(() => parsePort('80a'), TypeError);
});

test('invalid syntax: spaces', () => {
  assert.throws(() => parsePort(' 80 '), TypeError);
});

// Test out-of-range values
test('out of range: port 0', () => {
  assert.throws(() => parsePort('0'), RangeError);
});

test('out of range: port -1', () => {
  assert.throws(() => parsePort('-1'), RangeError);
});

test('out of range: port 65536', () => {
  assert.throws(() => parsePort('65536'), RangeError);
});

test('out of range: port 100000', () => {
  assert.throws(() => parsePort('100000'), RangeError);
});

// Test numeric input types
test('numeric input: number 8080', () => {
  assert.equal(parsePort(8080), 8080);
});

test('numeric input: number 1', () => {
  assert.equal(parsePort(1), 1);
});

test('numeric input: number 65535', () => {
  assert.equal(parsePort(65535), 65535);
});

// Test error messages
test('error message for invalid syntax', () => {
  try {
    parsePort('abc');
    assert.fail('Expected TypeError');
  } catch (e) {
    assert.equal(e.message, 'invalid port');
  }
});

test('error message for out-of-range', () => {
  try {
    parsePort('0');
    assert.fail('Expected RangeError');
  } catch (e) {
    assert.equal(e.message, 'port range');
  }
});"}

