});

// Test invalid syntax
test('invalid syntax: non-numeric string', () => {
  assert.throws(() => parsePort('abc'), TypeError);
});

test('invalid syntax: empty string', () => {
  assert.throws(() => parsePort(''), TypeError);
});

test('invalid syntax: negative number string', () => {
  assert.throws(() => parsePort('-80'), TypeError);
});

test('invalid syntax: float string', () => {
  assert.throws(() => parsePort('80.5'), TypeError);
});

test('invalid syntax: decimal point without digits', () => {
  assert.throws(() => parsePort('.'), TypeError);
});

test('invalid syntax: letters and numbers', () => {
  assert.throws(() => parsePort('80a'), TypeError);
});

test('invalid syntax: spaces', () => {
  assert.throws(() => parsePort(' 80 '), TypeError);
});

// Test out-of-range values
test('out of range: port 0', () => {
  assert.throws(() => parsePort('0'), RangeError);
});

test('out of range: port -1', () => {
  assert.throws(() => parsePort('-1'), TypeError);
});

test('out of range: port 65536', () => {
